import{_ as l,a0 as a,w as r,s as d,ao as p,I as s,x as i,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"如何轻松安装 Debian Linux 系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何轻松安装 Debian Linux 系统 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何轻松安装 Debian Linux 系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何轻松安装 Debian Linux 系统 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210827 How to Easily Install Debian Linux","title":"如何轻松安装 Debian Linux 系统","tag":"202109","desc":""},"relativePath":"202109/20210827 How to Easily Install Debian Linux.md","filePath":"[post].md"}'),b={name:"202109/20210827 How to Easily Install Debian Linux.md"};function u(m,t,f,D,w,g){const n=a("Link");return r(),d("div",null,[t[51]||(t[51]=p('<h1 id="如何轻松安装-debian-linux-系统" tabindex="-1">如何轻松安装 Debian Linux 系统 <a class="header-anchor" href="#如何轻松安装-debian-linux-系统" aria-label="Permalink to “如何轻松安装 Debian Linux 系统”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202109/16/123647x9uz7zjjqrq0qwkk.jpg" alt=""></p><p>安装 Debian 的轻松程度依赖于选择什么镜像。</p><p>如果你使用 Debain 官网的默认 ISO 镜像，安装 Debian 就比较费劲。你会卡在这种界面，让你从外部可移动介质上安装网络驱动。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Debian-firmware.png?resize=800%2C600&amp;ssl=1" alt="对于新用户来说，从默认的 ISO 中安装 Debian 是有问题的"></p><p>当然你可以花时间去排除这个故障，但这让事情变得没有必要的复杂。</p><p>不用担心，让我来展示如何轻松地简单安装 Debian。</p><h3 id="轻松安装-debian-桌面系统的方法" tabindex="-1">轻松安装 Debian 桌面系统的方法 <a class="header-anchor" href="#轻松安装-debian-桌面系统的方法" aria-label="Permalink to “轻松安装 Debian 桌面系统的方法”">​</a></h3><p>在你查看这些步骤之前，请确认以下准备工作：</p><ul><li>一个至少 4GB 大小的 USB 盘。</li><li>一个连接了互联网的系统（可以是要安装 Debian 的同一个机器）。</li><li>一个要安装的 Debian 的机器。它将会清理掉系统上所有数据，因此请复制重要数据到其他外部磁盘</li></ul>',10)),s("p",null,[t[1]||(t[1]=i("你需要为 Debian 准备什么样配置的机器？这取决于你想用什么类型的 ",-1)),e(n,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:o(()=>[...t[0]||(t[0]=[i("桌面环境",-1)])]),_:1}),t[2]||(t[2]=i("。例如，GNOME 桌面系统可以在 4GB 内存上运行，但在 8GB 内存上更流畅一些。如果你只有 4GB 或更少的内存，还是建议尝试 KDE、Cinnamon 或 Xfce 桌面系统。",-1))]),s("p",null,[t[4]||(t[4]=i("Debian 支持 ",-1)),e(n,{href:"https://itsfoss.com/32-bit-64-bit-ubuntu/"},{default:o(()=>[...t[3]||(t[3]=[i("32 位和 64 位的指令架构",-1)])]),_:1}),t[5]||(t[5]=i("。你需要根据你的 CPU 指令架构选择对应的 Debian ISO 镜像。",-1))]),t[52]||(t[52]=s("p",null,"你的系统应该至少要有 25GB 可用的硬盘空间。越多越好。",-1)),t[53]||(t[53]=s("blockquote",null,[s("p",null,[s("strong",null,"警告！")]),s("p",null,"这个方法会移除磁盘上所有其他操作系统及其数据。"),s("p",null,"你可以保存你后面还需要用的个人信息、文档、照片等到外部 USB 盘或云存储中。")],-1)),t[54]||(t[54]=s("p",null,"在这个教程中，我将展示安装带有 GNOME 桌面环境的 Debian 11 Bullseye 的步骤。即使你选择其他的桌面环境，步骤也应该是一样的。",-1)),s("p",null,[t[8]||(t[8]=i("这个教程是在 GPT 分区的 UEFI 系统上测试的。如果你的系统是 ",-1)),e(n,{href:"https://itsfoss.com/check-mbr-or-gpt/"},{default:o(()=>[...t[6]||(t[6]=[i("MBR 而不是 GPT",-1)])]),_:1}),t[9]||(t[9]=i("，或是 ",-1)),e(n,{href:"https://itsfoss.com/check-uefi-or-bios/"},{default:o(()=>[...t[7]||(t[7]=[i("传统的 BIOS 而不是 UEFI",-1)])]),_:1}),t[10]||(t[10]=i("，那么创建",-1)),t[11]||(t[11]=s("ruby",null,[i("临场"),s("rt",null,"Live")],-1)),t[12]||(t[12]=i(" USB 盘的步骤有一点不同。",-1))]),t[55]||(t[55]=p('<h4 id="步骤-1-获取正确的-debian-iso-镜像" tabindex="-1">步骤 1：获取正确的 Debian ISO 镜像 <a class="header-anchor" href="#步骤-1-获取正确的-debian-iso-镜像" aria-label="Permalink to “步骤 1：获取正确的 Debian ISO 镜像”">​</a></h4><p>在安装 Debian 过程中，选择正确的 ISO 镜像就已经成功一半了。令人惊讶的是，对于一个新的 Debian 用户来说，要浏览 Debian 的网站并找到最轻松好用的 ISO 真的很困难。</p><p>如果你点击 Debian 官网的下载按钮，它会下载一个最小化的网络安装文件，这对普通用户来说是非常复杂的。请 <strong>不要</strong> 使用这个。</p><p>反而，你应该用<ruby>临场<rt>Live</rt></ruby> ISO。但这里要注意，有一些单独的含有非自由软件（以包括网络硬件的驱动程序）的版本。</p><p>你应该下载这个非自由版的临场 ISO 镜像。不过另一个问题是，你不会在网站的显著位置注意到它，而且有各种架构的 BT 种子或直接下载的 URL。</p><p>让我把这些链接放在这里：</p>',6)),s("ul",null,[s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/"},{default:o(()=>[...t[13]||(t[13]=[i("32 位和 64 位的主仓地址",-1)])]),_:1})]),s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/amd64/iso-hybrid/"},{default:o(()=>[...t[14]||(t[14]=[i("Debian 11 官方下载",-1)])]),_:1})]),s("li",null,[e(n,{href:"https://cdimage.debian.org/images/unofficial/non-free/images-including-firmware/11.0.0-live+nonfree/amd64/bt-hybrid/"},{default:o(()=>[...t[15]||(t[15]=[i("Debian 11 种子地址",-1)])]),_:1})])]),t[56]||(t[56]=s("p",null,"你会看到几个文件，文件名中提到了桌面环境。选择一种你要的桌面环境。直接下载的话，直接点击 .iso 结尾的链接即可。",-1)),t[57]||(t[57]=s("p",null,[s("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/downloading-Debian-live-non-free-iso.png?resize=800%2C490&ssl=1",alt:"下载非自由版的临场 Debian ISO"})],-1)),t[58]||(t[58]=s("p",null,"一旦你有了对应的 ISO 下载包，剩下就是和其他 Linux 发行版一样的标准安装流程了。",-1)),t[59]||(t[59]=s("h4",{id:"步骤-2-创建一个-debian-的临场-usb-盘",tabindex:"-1"},[i("步骤 2: 创建一个 Debian 的临场 USB 盘 "),s("a",{class:"header-anchor",href:"#步骤-2-创建一个-debian-的临场-usb-盘","aria-label":"Permalink to “步骤 2: 创建一个 Debian 的临场 USB 盘”"},"​")],-1)),t[60]||(t[60]=s("p",null,"将 USB 盘插入你的系统。在用之前最好格式化一下，反正它最终也会被格式化的。",-1)),t[61]||(t[61]=s("p",null,"你可以根据你的选择使用任何临场 USB 创建工具。如果你使用 Windows，可以使用 Rufus。我们在这里使用 Etcher，因为这个工具在 Windows 和 Linux 都可以用。",-1)),t[62]||(t[62]=s("p",null,"从它的官网下载 Etcher。",-1)),s("ul",null,[s("li",null,[e(n,{href:"https://www.balena.io/etcher/"},{default:o(()=>[...t[16]||(t[16]=[i("下载 Etcher",-1)])]),_:1})])]),s("p",null,[t[18]||(t[18]=i("我专门写过一篇 ",-1)),e(n,{href:"https://itsfoss.com/install-etcher-linux/"},{default:o(()=>[...t[17]||(t[17]=[i("在 Linux 下使用 Etcher 的教程",-1)])]),_:1}),t[19]||(t[19]=i("，因此这里我就不深入介绍了。只要运行下载的可执行程序，浏览找到 Debian 的 ISO 镜像，确认选择正确的 USB 盘，然后点击 “Flash” 按钮即可。",-1))]),t[63]||(t[63]=s("p",null,[s("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/creating-live-debian-usb-with-etcher-800x518.png?resize=800%2C518&ssl=1",alt:"用 Etcher 创建 Debian 的临场 USB 盘"})],-1)),t[64]||(t[64]=s("p",null,"不一会就创建好临场 USB 盘了。创建好之后，就可以开机引导了。",-1)),t[65]||(t[65]=s("h4",{id:"步骤-3-从临场-usb-盘引导启动",tabindex:"-1"},[i("步骤 3：从临场 USB 盘引导启动 "),s("a",{class:"header-anchor",href:"#步骤-3-从临场-usb-盘引导启动","aria-label":"Permalink to “步骤 3：从临场 USB 盘引导启动”"},"​")],-1)),s("p",null,[t[21]||(t[21]=i("重启你要安装 Debian 的机器。当显示制造商标识的时候，按下 ",-1)),t[22]||(t[22]=s("code",null,"F2",-1)),t[23]||(t[23]=i("、",-1)),t[24]||(t[24]=s("code",null,"F10",-1)),t[25]||(t[25]=i(" 或 ",-1)),t[26]||(t[26]=s("code",null,"F12",-1)),t[27]||(t[27]=i(" 等键进入开机引导设置界面。你也可以从 Windows ",-1)),e(n,{href:"https://itsfoss.com/access-uefi-settings-windows-10/"},{default:o(()=>[...t[20]||(t[20]=[i("进入到 UEFI 固件设置界面",-1)])]),_:1}),t[28]||(t[28]=i("。",-1))]),s("p",null,[t[30]||(t[30]=i("有些机器如果启用了",-1)),t[31]||(t[31]=s("ruby",null,[i("安全启动"),s("rt",null,"secure boot")],-1)),t[32]||(t[32]=i("功能，就不允许从临场 USB 盘引导。如果是这种情况，请 ",-1)),e(n,{href:"https://itsfoss.com/disable-secure-boot-windows/"},{default:o(()=>[...t[29]||(t[29]=[i("从 BIOS 设置里禁用安全启动",-1)])]),_:1})]),t[66]||(t[66]=p('<p>不同的的制造商在界面上会有一些差异。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8.jpg?resize=700%2C525&amp;ssl=1" alt=""></p><p>你在 BIOS 里做了修改之后，按下 <code>F10</code> 保存并退出。你的系统将会重新启动。</p><p>再一次，当看到制造商的标识后按下 <code>F2</code>、<code>F10</code> 或 <code>F12</code> 查看引导配置。你应该可以看到从 USB 引导的选项，然后选中它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/04/boot-from-windows-disk-ventoy.jpg?resize=800%2C611&amp;ssl=1" alt=""></p><p>一会儿就会看到如下图的显示界面，选择第一个选项。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/debian-live-boot-screen.png?resize=617%2C432&amp;ssl=1" alt="Debian 启动界面"></p><h4 id="步骤-4-开始安装-debian" tabindex="-1">步骤 4: 开始安装 Debian <a class="header-anchor" href="#步骤-4-开始安装-debian" aria-label="Permalink to “步骤 4: 开始安装 Debian”">​</a></h4><p>当你进入临场 Debian 会话，如果你使用 GNONE 桌面，它呈现一个欢迎界面，可以在此选择你的键盘和语言。当你看到这些界面时，只需要点击下一步。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/debian-live-welcome-screen.png?resize=800%2C450&amp;ssl=1" alt="Debian 临场欢迎界面"></p><p>欢迎界面之后，按下 <code>Windows</code> / <code>Super</code> 键进入活动区。你应该可以看到 Debian 的安装按钮。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/start-Debian-installation-800x473.webp" alt="开始安装 Debian"></p>',12)),s("p",null,[t[34]||(t[34]=i("它会打开一个友好的 ",-1)),e(n,{href:"https://calamares.io/"},{default:o(()=>[...t[33]||(t[33]=[i("Calamares 图形安装器",-1)])]),_:1}),t[35]||(t[35]=i("。从这里开始事情就比较简单了，",-1))]),t[67]||(t[67]=p('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-1.png?resize=800%2C441&amp;ssl=1" alt="Debian 11 Calamares 图形安装器"></p><p>它会让你选择你的地理位置和时区。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-2-800x441.webp" alt="选择你的地理位置和时区"></p><p>下一个界面，会让你选择键盘类型。这儿请 <strong>注意</strong>。你的键盘会根据你所选的位置自动选择。例如，我的位置是印度，它会自动默认选择印度键盘和印地语。我需要将其改为印度英语。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-4-800x441.webp" alt="选择键盘类型"></p><p>下一个界面是关于磁盘分区和要安装 Debian 的地方。在本文中，把 Debian 作为你电脑上唯一的操作系统来安装。</p><p>最简单的方法是直接选择 “<ruby>擦除磁盘<rt>Erase Disk</rt></ruby>”。除了必须的 ESP 分区和交换分区外，Debian 会把其他所有东西都放在根挂载点（<code>/</code>）上。实际上，下面显示了你所选的安装方式后的磁盘布局。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-5.png?resize=800%2C441&amp;ssl=1" alt="磁盘分区"></p><p>如果你想把事情掌握在自己手中，你也可以选择手动分区，选择分配给 <code>/</code>、<code>/home</code>、<code>/boot</code> 或交换分区的大小。只有在你知道自己在做什么时，才可以这样做。</p><p>下一界面，你需要提供用户名和密码。但它不会设置 root 的密码，并将其保持为空。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-6.png?resize=800%2C441&amp;ssl=1" alt="设置用户名和密码"></p><p>这也意味着你可以用新创建的用户使用 <code>sudo</code> 。在“复杂的 Debian 安装”中，你也可以设置 root 密码，但这样你就必须手动将普通用户添加到 <code>sudoer</code> 列表。看看，这种安装过程是不是对新手来说很容易？</p><p>在继续实际安装之前，它会呈现你所做的选择的汇总信息。如果没有问题，就可以点击“<ruby>安装<rt>Install</rt></ruby>”按钮。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-7-800x500.webp" alt="安装配置的汇总信息"></p><p>现在只需要等待安装完成。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-8.png?resize=800%2C500&amp;ssl=1" alt="安装 Debian"></p><p>几分钟后就会完成安装。当安装完成，它会提示重启。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Installing-Debian-9.png?resize=800%2C500&amp;ssl=1" alt="完成 Debian 安装"></p><p>重启系统后如果一切顺利，你应该可以看到 Debian 的 GRUB 界面。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/debian-boot-screen.webp" alt="Debian 启动画面"></p><h3 id="疑难解答-如果系统没有启动到-debian" tabindex="-1">疑难解答（如果系统没有启动到 Debian） <a class="header-anchor" href="#疑难解答-如果系统没有启动到-debian" aria-label="Permalink to “疑难解答（如果系统没有启动到 Debian）”">​</a></h3><p>我遇到情况是，我的 Dell 系统不能识别任何要引导的操作系统。这很奇怪，我看见 Debian 经创建了一个 ESP 分区。</p><p>如果你也是同样的情况，进去 BIOS 配置里。检查<ruby>启动顺序<rt>Boot Sequence</rt></ruby>，如果你看不到任何东西，就点击“<ruby>新增引导选项<rt>Add Boot Option</rt></ruby>”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/add-new-boot-option.webp" alt="增加新的启动选项"></p><p>它会提供一个增加 EFI 文件的选项。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/add-efi-file-for-boot-option.webp" alt="选择 EFI 文件"></p><p>由于在安装过程中 Debian 创建了 ESP 分区，因此一个包含必要文件的 <code>EFI</code> 目录已经创建好了。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-efi-file-boot-option.webp" alt="选择 EFI 目录"></p><p>它会显示一个 <code>Debian</code> 目录及其他目录。选择 <code>Debian</code> 目录。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-debian-folder-for-uefi.webp" alt="选择 Debian 目录"></p><p>在 <code>Debian</code> 目录，你将看到 <code>grubx64.efi</code>、<code>shimx64.efi</code> 等文件。请选择 <code>shimx64.efi</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/select-shim-boot.webp" alt="选择 shimx64.efi"></p><p>你需要给这个文件一个合适的名字。最后的界面应该如下:</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/new-boot-option.webp" alt="增加 efi 文件的新启动选项"></p><p>现在你应该有了这个启动选项。因为我命名为 <code>Debian</code>，它显示了两个 <code>Debian</code> 引导选项（我猜其中一个是从 efi 文件来的）。按下 <code>F10</code> 保存退出 BIOS 的配置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/new-boot-option-added.webp" alt="新增的启动选项"></p><p>现在启动你的系统，你可以看到带有 Debian 启动选项的 GRUB 界面了。你现在可以体验 Debian 了。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/08/debian-boot-screen.webp" alt=""></p><h3 id="你能安装-debian-吗" tabindex="-1">你能安装 Debian 吗？ <a class="header-anchor" href="#你能安装-debian-吗" aria-label="Permalink to “你能安装 Debian 吗？”">​</a></h3><p>我写这篇文章的目的是让事情变得轻松点。并不是说你不能从默认的网络安装程序 ISO 来安装，只是它需要花更多的精力。</p><p>这个教程对你安装 Debian 有帮助吗？你如果还是有问题，请在下面留言给我，我会尽力提供帮助。</p><hr>',42)),s("p",null,[t[37]||(t[37]=i("via: ",-1)),e(n,{href:"https://itsfoss.com/install-debian-easily/"},{default:o(()=>[...t[36]||(t[36]=[i("https://itsfoss.com/install-debian-easily/",-1)])]),_:1})]),s("p",null,[t[42]||(t[42]=i("作者：",-1)),e(n,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[38]||(t[38]=[i("Abhishek Prakash",-1)])]),_:1}),t[43]||(t[43]=i(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[39]||(t[39]=[i("lujun9972",-1)])]),_:1}),t[44]||(t[44]=i(" 译者：",-1)),e(n,{href:"https://github.com/guevaraya"},{default:o(()=>[...t[40]||(t[40]=[i("巴龙",-1)])]),_:1}),t[45]||(t[45]=i(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[41]||(t[41]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[48]||(t[48]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[46]||(t[46]=[i("LCTT",-1)])]),_:1}),t[49]||(t[49]=i(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[47]||(t[47]=[i("Linux中国",-1)])]),_:1}),t[50]||(t[50]=i(" 荣誉推出",-1))])])}const T=l(b,[["render",u]]);export{I as __pageData,T as default};
